def uv_project(ob,scale=.8):
 uv=ob.data.uv_layers.new(name='ShipyardMetricUV')
 for p in ob.data.polygons:
  ax=max(range(3),key=lambda i:abs(p.normal[i]));a,b=([1,2] if ax==0 else [0,2] if ax==1 else [0,1])
  for li in p.loop_indices:
   co=ob.data.vertices[ob.data.loops[li].vertex_index].co;uv.data[li].uv=(co[a]/scale,co[b]/scale)

def box(name,center,size,mat=stone,bevel=.025):
 sx,sy,sz=[v/2 for v in size]
 vs=[(-sx,-sy,-sz),(sx,-sy,-sz),(sx,sy,-sz),(-sx,sy,-sz),(-sx,-sy,sz),(sx,-sy,sz),(sx,sy,sz),(-sx,sy,sz)]
