def beam(name,p0,p1,w=.18,d=None,role='frame'):
 d=d or w;a=Vector(p0);b=Vector(p1);L=(b-a).length
 ob=box(name,(a+b)/2,(L,w,d),wood[role],min(.012,w*.06));ob.rotation_mode='QUATERNION';ob.rotation_quaternion=(b-a).to_track_quat('X','Z')
 uv=ob.data.uv_layers[0];uv.name='ShipyardPhysicalTimber';row={'frame':0,'cargo_frame':1,'trim':2,'deck':3}[role]
 shift=(22-L)*((sum(map(ord,name))*17)%97)/97
 for p in ob.data.polygons:
  ax=max(range(3),key=lambda i:abs(p.normal[i]))
  for li in p.loop_indices:
   q=ob.data.vertices[ob.data.loops[li].vertex_index].co
